<?php
session_start(); require __DIR__.'/config.php';
$dataDir=__DIR__.'/data'; $settingsFile=$dataDir.'/settings.json'; $devicesFile=$dataDir.'/devices.json';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function go(){header('Location: index.php');exit;}
function readj($f,$d){if(!is_file($f))return $d;$v=json_decode(file_get_contents($f),true);return is_array($v)?$v:$d;} function savej($f,$v){file_put_contents($f,json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);}
function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function pathenc($p){return implode('/',array_map('rawurlencode',explode('/',trim($p,'/'))));}
function gh($method,$path,$body=null){if(GITHUB_TOKEN==='COLE_SEU_TOKEN_FINE_GRAINED_AQUI')throw new Exception('Preencha o GITHUB_TOKEN em config.php.');$url='https://api.github.com/repos/'.rawurlencode(GITHUB_OWNER).'/'.rawurlencode(GITHUB_REPOSITORY).'/contents/'.pathenc($path);if($method==='GET')$url.='?ref='.rawurlencode(GITHUB_BRANCH);$h=['Accept: application/vnd.github+json','Authorization: Bearer '.GITHUB_TOKEN,'X-GitHub-Api-Version: 2022-11-28','User-Agent: ConfigBox-Admin'];$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$h,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>90]);if($body!==null){$h[]='Content-Type: application/json';curl_setopt($c,CURLOPT_HTTPHEADER,$h);curl_setopt($c,CURLOPT_POSTFIELDS,json_encode($body,JSON_UNESCAPED_UNICODE));}$r=curl_exec($c);$err=curl_error($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($r===false||$err)throw new Exception('Falha de conexão com o GitHub: '.$err);$j=json_decode($r,true);if($code<200||$code>=300)throw new Exception(is_array($j)&&isset($j['message'])?$j['message']:'GitHub HTTP '.$code);return $j;}
function files($folder){$items=gh('GET',$folder);$out=[];if(!is_array($items))return $out;foreach($items as $i)if(($i['type']??'')==='file')$out[]=['name'=>$i['name'],'path'=>$i['path'],'sha'=>$i['sha']??'','size'=>(int)($i['size']??0)];usort($out,function($a,$b){return strcasecmp($a['name'],$b['name']);});return $out;}
function safe($n){$n=trim(basename($n));if($n===''||$n==='.'||$n==='..'||strpos($n,"\0")!==false)throw new Exception('Nome inválido.');return $n;}
function postcheck(){if(empty($_SESSION['admin']))go();if(!isset($_POST['csrf'])||!hash_equals($_SESSION['csrf'],$_POST['csrf']))throw new Exception('Sessão expirada.');}
$msg=null;$type='ok';$settings=readj($settingsFile,['plan_active'=>true,'lock_message'=>'','dialog_message'=>'']);$devices=readj($devicesFile,[]);
try{
 if(isset($_GET['logout'])){session_destroy();go();}
 if(isset($_POST['login'])){if(ADMIN_PASSWORD==='DEFINA_UMA_SENHA_FORTE_AQUI'||!hash_equals(ADMIN_PASSWORD,(string)($_POST['password']??'')))throw new Exception('Senha inválida.');$_SESSION['admin']=true;csrf();go();}
 if($_SERVER['REQUEST_METHOD']==='POST'){postcheck();
  if(isset($_POST['save_control'])){$settings['plan_active']=isset($_POST['plan_active']);$settings['lock_message']=trim((string)($_POST['lock_message']??''));$settings['dialog_message']=trim((string)($_POST['dialog_message']??''));savej($settingsFile,$settings);$msg='Controle do ativador salvo.';}
  if(isset($_POST['device_action'])){$id=(string)($_POST['device_id']??'');foreach($devices as &$d)if(($d['device_id']??'')===$id){$d['blocked']=$_POST['device_action']==='block';$d['message']=trim((string)($_POST['device_message']??''));}$devices=array_values($devices);savej($devicesFile,$devices);$msg='Status do aparelho atualizado.';}
  if(isset($_POST['upload_configs'])){$current=files(GITHUB_CONFIG_FOLDER);$map=[];foreach($current as $f)$map[$f['name']]=$f;$count=0;$up=$_FILES['configs']??null;if(!$up||!is_array($up['name']))throw new Exception('Escolha configurações.');foreach($up['name'] as $i=>$original){if(($up['error'][$i]??4)!==0)continue;$name=safe($original);$body=['message'=>(isset($map[$name])?'Atualizar ':'Adicionar ').$name,'content'=>base64_encode(file_get_contents($up['tmp_name'][$i])),'branch'=>GITHUB_BRANCH];if(isset($map[$name]))$body['sha']=$map[$name]['sha'];gh('PUT',GITHUB_CONFIG_FOLDER.'/'.$name,$body);$count++;}$msg=$count.' configuração(ões) enviada(s).';}
  if(isset($_POST['upload_apk'])){$up=$_FILES['unitv_apk']??null;if(!$up||($up['error']??4)!==0)throw new Exception('Escolha um APK.');if(strtolower(pathinfo($up['name'],PATHINFO_EXTENSION))!=='apk')throw new Exception('Envie um arquivo .apk.');$old=files(GITHUB_APK_FOLDER);$existing=null;foreach($old as $f)if($f['name']==='unitv.apk')$existing=$f;$body=['message'=>'Atualizar unitv.apk pelo Admin','content'=>base64_encode(file_get_contents($up['tmp_name'])),'branch'=>GITHUB_BRANCH];if($existing)$body['sha']=$existing['sha'];gh('PUT',GITHUB_APK_FOLDER.'/unitv.apk',$body);$msg='unitv.apk enviado para a pasta unitvapk.';}
 }
}catch(Throwable $x){$msg=$x->getMessage();$type='err';}
$logged=!empty($_SESSION['admin']);$configs=[];$apks=[];if($logged){try{$configs=files(GITHUB_CONFIG_FOLDER);$apks=files(GITHUB_APK_FOLDER);$settings=readj($settingsFile,$settings);$devices=readj($devicesFile,$devices);}catch(Throwable $x){$msg=$x->getMessage();$type='err';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ConfigBox Admin</title><style>:root{font-family:system-ui;color:#0f172a;background:#f1f5f9}*{box-sizing:border-box}body{margin:0}.wrap{max-width:920px;margin:auto;padding:22px 14px 50px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:18px;margin:14px 0;box-shadow:0 8px 24px #0f172a0b}.login{max-width:450px;margin:12vh auto}.h1{font-size:26px;margin:0 0 8px}.h2{font-size:18px;margin:3px 0 12px}.eyebrow{color:#2563eb;font-size:10px;font-weight:800;letter-spacing:1.3px;margin:0 0 5px}.muted{color:#64748b;font-size:13px;line-height:1.5}.input,.textarea{width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:10px;font:inherit;margin:4px 0 10px}.textarea{min-height:70px;resize:vertical}.button{border:0;border-radius:10px;padding:11px 15px;font-weight:800;cursor:pointer}.primary{background:#2563eb;color:#fff}.danger{background:#fee2e2;color:#991b1b}.ok,.err{padding:11px;border-radius:10px;margin:12px 0;font-size:13px}.ok{background:#dcfce7;color:#166534}.err{background:#fee2e2;color:#991b1b}.top,.row,.device{display:flex;align-items:center;justify-content:space-between;gap:12px}.top{margin-bottom:15px}.banner{background:#0f172a;color:#fff;border-radius:14px;padding:14px;margin-bottom:14px}.banner small{color:#bfdbfe;font-family:monospace}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.file,.device{border:1px solid #e2e8f0;border-radius:10px;padding:10px;margin:7px 0}.file span,.device-info{min-width:0;overflow:hidden;text-overflow:ellipsis}.device-info{flex:1}.device small{display:block;color:#64748b;margin-top:3px}.badge{font-size:11px;border-radius:99px;padding:4px 8px;background:#dcfce7;color:#166534}.badge.blocked{background:#fee2e2;color:#991b1b}@media(max-width:650px){.grid{grid-template-columns:1fr}.device{align-items:flex-start;flex-wrap:wrap}.device form{width:100%}}
</style></head><body><main class="wrap"><?php if(!$logged):?><section class="card login"><p class="eyebrow">CONFIGBOX ADMIN</p><h1 class="h1">Controle do ativador</h1><p class="muted">Bloqueie o plano, aparelhos e publique configurações ou o APK do UniTV.</p><?php if($msg):?><div class="<?=e($type)?>"><?=e($msg)?></div><?php endif;?><form method="post"><input class="input" type="password" name="password" placeholder="Senha administrativa" required><button class="button primary" name="login" value="1">Entrar</button></form></section><?php else:?><header class="top"><div><p class="eyebrow">PAINEL ADMIN</p><h1 class="h1">Controle e arquivos</h1></div><a class="button" href="?logout=1">Sair</a></header><div class="banner"><small><?=e(GITHUB_OWNER.'/'.GITHUB_REPOSITORY)?></small></div><?php if($msg):?><div class="<?=e($type)?>"><?=e($msg)?></div><?php endif;?><section class="card"><p class="eyebrow">CONTROLE REMOTO</p><h2 class="h2">Plano e mensagens do app</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label><input type="checkbox" name="plan_active" <?=$settings['plan_active']?'checked':''?>> Ativador liberado</label><label class="muted">Mensagem mostrada quando bloqueado<textarea class="textarea" name="lock_message"><?=e($settings['lock_message']??'')?></textarea></label><label class="muted">Diálogo exibido ao abrir o app<textarea class="textarea" name="dialog_message"><?=e($settings['dialog_message']??'')?></textarea></label><button class="button primary" name="save_control" value="1">Salvar controle</button></form></section><div class="grid"><section class="card"><p class="eyebrow">CONFIGS</p><h2 class="h2">Enviar configurações</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="input" type="file" name="configs[]" multiple><button class="button primary" name="upload_configs" value="1">Enviar configs</button></form><p class="muted"><?=count($configs)?> arquivo(s) na pasta configs.</p></section><section class="card"><p class="eyebrow">UNITV APK</p><h2 class="h2">Enviar nova atualização</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="input" type="file" name="unitv_apk" accept=".apk" required><button class="button primary" name="upload_apk" value="1">Enviar APK para unitvapk</button></form><p class="muted">O arquivo será publicado sempre como unitv.apk.</p></section></div><section class="card"><p class="eyebrow">APARELHOS CADASTRADOS</p><h2 class="h2"><?=count($devices)?> aparelho(s)</h2><?php if(!$devices):?><p class="muted">Nenhum aparelho consultou o Admin ainda.</p><?php else:foreach($devices as $d):?><div class="device"><div class="device-info"><strong><?=e($d['model']??'Modelo desconhecido')?></strong><small>Android ID: <?=e($d['device_id']??'')?> · IMEI: <?=e($d['imei']??'não disponível')?></small><small>Último acesso: <?=e($d['last_seen']??'')?></small></div><span class="badge <?=$d['blocked']?'blocked':''?>"><?=$d['blocked']?'Bloqueado':'Liberado'?></span><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="device_id" value="<?=e($d['device_id']??'')?>"><input class="input" name="device_message" placeholder="Mensagem deste aparelho" value="<?=e($d['message']??'')?>"><button class="button <?=$d['blocked']?'primary':'danger'?>" name="device_action" value="<?=$d['blocked']?'unblock':'block'?>"><?=$d['blocked']?'Desbloquear':'Bloquear aparelho'?></button></form></div><?php endforeach;endif;?></section><p class="muted" style="text-align:center">O app usa Android ID como identificador principal. O IMEI pode não ser fornecido pelo Android.</p><?php endif;?></main></body></html>
